-- 架空3店舗のデモデータ。src/data/demo-seed.ts から npm run seed:sql で再生成する。
-- 再実行すると3店舗を削除して作り直す。FAQ・メニュー・引き継ぎ・shop_members も消える。
begin;

delete from public.shops
where slug in ('komorebi', 'lumiere', 'yasuragi')
   or id in ('11111111-1111-4111-8111-111111111111'::uuid, '22222222-2222-4222-8222-222222222222'::uuid, '33333333-3333-4333-8333-333333333333'::uuid);




commit;
